  {
    id: 'getnet',
    name: 'Getnet',
    desc: 'Gateway de pagamento — PIX, Boleto, Cartão. Integrado ao módulo de billing.',
    icon: 'billing',
    connected: true,
    badge: 'Ativo',
    badgeColor: '#22c55e',
  },
  {
    id: 'supabase',
    name: 'Supabase',
    desc: 'Banco de dados e autenticação da plataforma.',
    icon: 'shield',
    connected: true,
    badge: 'Ativo',
    badgeColor: '#22c55e',
  },
  {
