// ---------------------------------------------------------------------------
// Utilitários
// ---------------------------------------------------------------------------
function normalizeState(status) {
  if (!status) return 'connecting';
  const s = String(status).toLowerCase();
  if (s === 'connected') return 'connected';
  if (s === 'offline' || s === 'disconnected') return 'disconnected';
  return 'connecting';
}

const WARMUP_BUBBLES = [
